import React from 'react';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { Users, TrendingUp, DollarSign, Clock, Bell } from 'lucide-react';
import { employees, leaveRequests, payrollData, announcements, departments } from '../data/mockData';

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div style={{ background:'var(--bg-card2)', border:'1px solid var(--border)', borderRadius:8, padding:'10px 14px' }}>
        <p style={{ color:'var(--text-2)', fontSize:12, marginBottom:4 }}>{label}</p>
        <p style={{ color:'var(--accent)', fontWeight:600 }}>${payload[0].value.toLocaleString()}</p>
      </div>
    );
  }
  return null;
};

export default function Dashboard() {
  const activeEmp   = employees.filter(e => e.status === 'Active').length;
  const pendingLeave = leaveRequests.filter(l => l.status === 'Pending').length;
  const totalPayroll = employees.reduce((s, e) => s + e.salary, 0);

  return (
    <div className="page">
      <div className="page-header">
        <h1>Good morning, Nayan 👋</h1>
        <p>Here's what's happening at AMBE AI TECHNOLOGIES today.</p>
      </div>

      <div className="stat-grid">
        <div className="stat-card blue">
          <div className="stat-label">Total Employees</div>
          <div className="stat-value blue">{employees.length}</div>
          <div className="stat-sub">↑ 1 hired this quarter</div>
          <Users size={20} className="stat-icon" />
        </div>
        <div className="stat-card green">
          <div className="stat-label">Active Today</div>
          <div className="stat-value green">{activeEmp}</div>
          <div className="stat-sub">1 on approved leave</div>
          <TrendingUp size={20} className="stat-icon" />
        </div>
        <div className="stat-card orange">
          <div className="stat-label">Monthly Payroll</div>
          <div className="stat-value orange">${totalPayroll.toLocaleString()}</div>
          <div className="stat-sub">SGD gross total</div>
          <DollarSign size={20} className="stat-icon" />
        </div>
        <div className="stat-card purple">
          <div className="stat-label">Pending Leaves</div>
          <div className="stat-value purple">{pendingLeave}</div>
          <div className="stat-sub">Awaiting approval</div>
          <Clock size={20} className="stat-icon" />
        </div>
      </div>

      <div className="card-grid-3" style={{ marginBottom:20 }}>
        <div className="card" style={{ marginBottom:0 }}>
          <div className="card-header"><div className="card-title">Payroll Trend (2025)</div></div>
          <ResponsiveContainer width="100%" height={180}>
            <AreaChart data={payrollData}>
              <defs>
                <linearGradient id="payGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%"  stopColor="#38bdf8" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="#38bdf8" stopOpacity={0} />
                </linearGradient>
              </defs>
              <XAxis dataKey="month" tick={{ fill:'#475569', fontSize:11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill:'#475569', fontSize:11 }} axisLine={false} tickLine={false} tickFormatter={v => `$${(v/1000).toFixed(0)}k`} />
              <Tooltip content={<CustomTooltip />} />
              <Area type="monotone" dataKey="totalPayout" stroke="#38bdf8" strokeWidth={2} fill="url(#payGrad)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        <div className="card" style={{ marginBottom:0 }}>
          <div className="card-header"><div className="card-title">Departments</div></div>
          <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
            {departments.map(d => (
              <div key={d.name}>
                <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, marginBottom:4 }}>
                  <span style={{ color:'var(--text-2)' }}>{d.name}</span>
                  <span style={{ color:d.color, fontWeight:600 }}>{d.headcount}</span>
                </div>
                <div className="progress-bar-wrap">
                  <div className="progress-bar" style={{ width:`${(d.headcount/employees.length)*100}%`, background:d.color }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="card-grid-2">
        <div className="card" style={{ marginBottom:0 }}>
          <div className="card-header">
            <div className="card-title">Team Members</div>
            <span className="badge badge-blue">{employees.length} total</span>
          </div>
          <div style={{ display:'flex', flexDirection:'column', gap:10 }}>
            {employees.slice(0,5).map(emp => (
              <div key={emp.id} style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
                <div className="emp-info">
                  <div className="emp-avatar">{emp.avatar}</div>
                  <div><div className="emp-name">{emp.name}</div><div className="emp-role">{emp.dept}</div></div>
                </div>
                <span className={`badge ${emp.status === 'Active' ? 'badge-green' : 'badge-orange'}`}>{emp.status}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="card" style={{ marginBottom:0 }}>
          <div className="card-header">
            <div className="card-title">Announcements</div>
            <Bell size={16} style={{ color:'var(--text-3)' }} />
          </div>
          {announcements.map(a => (
            <div key={a.id} className={`announcement ${a.priority}`}>
              <div className="ann-title">{a.title}</div>
              <div className="ann-date">{a.date}</div>
              <div className="ann-body">{a.body}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}