import React, { useState, useEffect } from 'react';
import { FileSearch, RefreshCw } from 'lucide-react';


function scoreResume(text) {
  const keywords = ['react', 'typescript', 'python', 'machine learning', 'aws', 'docker', 'hr', 'recruitment', 'product'];
  const clean = text.toLowerCase();
  return Math.min(100, Math.max(55, Math.floor(keywords.reduce((score, word) => score + (clean.includes(word) ? 7 : 0), 50))));
}

export default function Resumes() {
  const [candidates, setCandidates] = useState([]);
  useEffect(()=>{ fetch('/api/resumes').then(r=>r.json()).then(setCandidates).catch(()=>setCandidates([])); },[]);

  const handleScreen = () => {
    setCandidates(prev => prev.map(candidate => ({
      ...candidate,
      score: scoreResume(`${candidate.skills.join(' ')} ${candidate.appliedFor}`),
      status: (candidate.score||0) > 84 ? 'Shortlisted' : (candidate.score||0) > 75 ? 'Interview' : 'Review',
    })));
  };

  return (
    <div className="page">
      <div className="page-header"><h1>AI Resume Screening</h1><p>Review candidate resumes and see AI-driven screening scores.</p></div>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
        <div className="stat-grid" style={{ gridTemplateColumns:'repeat(3,1fr)', flex:1, gap:12 }}>
          <div className="stat-card blue"><div className="stat-label">Candidates</div><div className="stat-value blue">{candidates.length}</div></div>
          <div className="stat-card green"><div className="stat-label">Shortlisted</div><div className="stat-value green">{candidates.filter(c => c.status === 'Shortlisted').length}</div></div>
          <div className="stat-card orange"><div className="stat-label">Interviews</div><div className="stat-value orange">{candidates.filter(c => c.status === 'Interview').length}</div></div>
        </div>
        <button className="btn btn-primary" onClick={handleScreen}><RefreshCw size={16} /> Screen Resumes</button>
      </div>

      <div className="card" style={{ padding:0, overflow:'hidden' }}>
        <div className="table-wrap">
          <table>
            <thead><tr><th>Candidate</th><th>Role</th><th>Experience</th><th>Skills</th><th>Score</th><th>Status</th></tr></thead>
            <tbody>
              {candidates.map(candidate => (
                <tr key={candidate.id}>
                  <td>{candidate.name}</td>
                  <td>{candidate.appliedFor}</td>
                  <td>{candidate.experience} yrs</td>
                  <td>{candidate.skills.join(', ')}</td>
                  <td style={{ fontWeight:700 }}>{candidate.score}%</td>
                  <td>
                    <span className={`badge ${candidate.status === 'Shortlisted' ? 'badge-green' : candidate.status === 'Interview' ? 'badge-orange' : 'badge-blue'}`}>
                      {candidate.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card" style={{ marginTop:20, padding:'20px' }}>
        <div className="card-header"><div className="card-title"><FileSearch size={16} style={{ marginRight:8 }} />Screening Notes</div></div>
        <div style={{ marginTop:10, color:'var(--text-2)', lineHeight:1.7 }}>
          Candidate resumes are scored by matching skills and role keywords. Use the <strong>Screen Resumes</strong> action to refresh the AI score and identify top fits instantly.
        </div>
      </div>
    </div>
  );
}
