import React, { useState, useEffect } from 'react';
import { Plus, Check, X, Calendar } from 'lucide-react';


const leaveTypes = ['Annual','Medical','Childcare','Maternity','Paternity','Unpaid'];

export default function Leaves() {
  const [leaves, setLeaves]     = useState([]);
  const [tab, setTab]           = useState('All');
  const [showModal, setShowModal] = useState(false);
  const [form, setForm]         = useState({ empId:1, type:'Annual', from:'', to:'', reason:'' });

  const tabs     = ['All','Pending','Approved','Rejected'];
  const filtered = tab==='All' ? leaves : leaves.filter(l=>l.status===tab);
  const counts   = { All:leaves.length, Pending:leaves.filter(l=>l.status==='Pending').length, Approved:leaves.filter(l=>l.status==='Approved').length, Rejected:leaves.filter(l=>l.status==='Rejected').length };

  useEffect(()=>{
    fetch('/api/leaves').then(r=>r.json()).then(setLeaves).catch(()=>setLeaves([]));
  },[]);
  const [employees, setEmployees] = useState([]);
  useEffect(()=>{ fetch('/api/employees').then(r=>r.json()).then(setEmployees).catch(()=>setEmployees([])); },[]);

  const approve = async id => {
    const updated = leaves.map(x=>x.id===id?{...x,status:'Approved'}:x);
    setLeaves(updated);
    await fetch(`/api/leaves/${id}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status:'Approved' }) });
  };
  const reject  = async id => {
    const updated = leaves.map(x=>x.id===id?{...x,status:'Rejected'}:x);
    setLeaves(updated);
    await fetch(`/api/leaves/${id}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status:'Rejected' }) });
  };

  const calcDays = (from,to) => {
    if (!from||!to) return 0;
    return Math.max(1, Math.round((new Date(to)-new Date(from))/(1000*60*60*24))+1);
  };

  const submitLeave = async () => {
    if (!form.from||!form.to||!form.reason) return;
    const body = { empId:Number(form.empId), type:form.type, from:form.from, to:form.to, days:calcDays(form.from,form.to), status:'Pending', reason:form.reason };
    const res = await fetch('/api/leaves', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
    const created = await res.json();
    setLeaves(prev=>[...prev, created]);
    setShowModal(false);
    setForm({ empId:1, type:'Annual', from:'', to:'', reason:'' });
  };

  return (
    <div className="page">
      <div className="page-header"><h1>Leave Management</h1><p>Track, approve, and manage all employee leave requests.</p></div>

      <div className="stat-grid" style={{ gridTemplateColumns:'repeat(4,1fr)' }}>
        {[{label:'Total',val:counts.All,cls:'blue'},{label:'Pending',val:counts.Pending,cls:'orange'},{label:'Approved',val:counts.Approved,cls:'green'},{label:'Rejected',val:counts.Rejected,cls:'purple'}].map(s=>(
          <div key={s.label} className={`stat-card ${s.cls}`}>
            <div className="stat-label">{s.label}</div>
            <div className={`stat-value ${s.cls}`}>{s.val}</div>
          </div>
        ))}
      </div>

      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:16 }}>
        <div className="tabs">
              {tabs.map(t=>(
            <button key={t} className={`tab ${tab===t?'active':''}`} onClick={()=>setTab(t)}>
              {t} {counts[t]>0&&<span style={{ marginLeft:4, background:'var(--bg-hover)', borderRadius:99, padding:'0 6px', fontSize:11 }}>{counts[t]}</span>}
            </button>
          ))}
        </div>
        <button className="btn btn-primary" onClick={()=>setShowModal(true)}><Plus size={14}/> Apply Leave</button>
      </div>

      <div className="card" style={{ padding:0, overflow:'hidden' }}>
        <div className="table-wrap">
          <table>
            <thead><tr><th>Employee</th><th>Type</th><th>From</th><th>To</th><th>Days</th><th>Reason</th><th>Status</th><th>Actions</th></tr></thead>
            <tbody>
              {filtered.map(l=>(
                <tr key={l.id}>
                  <td><div className="emp-info"><div className="emp-avatar" style={{fontSize:11}}>{l.empName.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><span style={{fontSize:13,fontWeight:500}}>{l.empName}</span></div></td>
                  <td><span className="badge badge-blue">{l.type}</span></td>
                  <td style={{color:'var(--text-2)',fontSize:13}}>{l.from}</td>
                  <td style={{color:'var(--text-2)',fontSize:13}}>{l.to}</td>
                  <td style={{fontFamily:'var(--font-display)',fontWeight:600}}>{l.days}d</td>
                  <td style={{color:'var(--text-2)',fontSize:12,maxWidth:160}}>{l.reason}</td>
                  <td><span className={`badge ${l.status==='Approved'?'badge-green':l.status==='Pending'?'badge-orange':'badge-red'}`}>{l.status}</span></td>
                  <td>
                    {l.status==='Pending'&&(
                      <div style={{display:'flex',gap:6}}>
                        <button className="btn btn-sm btn-outline" style={{color:'var(--accent3)',borderColor:'var(--accent3)'}} onClick={()=>approve(l.id)}><Check size={12}/> Approve</button>
                        <button className="btn btn-sm btn-danger" onClick={()=>reject(l.id)}><X size={12}/> Reject</button>
                      </div>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filtered.length===0&&<div style={{textAlign:'center',padding:40,color:'var(--text-3)'}}>No leave requests found.</div>}
        </div>
      </div>

      {showModal&&(
        <div className="modal-overlay" onClick={()=>setShowModal(false)}>
          <div className="modal" onClick={e=>e.stopPropagation()}>
            <div className="modal-title">Apply for Leave</div>
            <div className="modal-sub">Submit a new leave request for review.</div>
            <div className="form-grid">
              <div className="form-group" style={{gridColumn:'1/-1'}}>
                <label className="form-label">Employee</label>
                <select className="form-select" value={form.empId} onChange={e=>setForm({...form,empId:e.target.value})}>
                  {employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Leave Type</label>
                <select className="form-select" value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>
                  {leaveTypes.map(t=><option key={t}>{t}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Duration</label>
                <div style={{display:'flex',gap:8}}>
                  <input className="form-input" type="date" value={form.from} onChange={e=>setForm({...form,from:e.target.value})} />
                  <input className="form-input" type="date" value={form.to}   onChange={e=>setForm({...form,to:e.target.value})} />
                </div>
              </div>
              <div className="form-group" style={{gridColumn:'1/-1'}}>
                <label className="form-label">Reason</label>
                <input className="form-input" placeholder="Briefly describe the reason…" value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} />
              </div>
            </div>
            {form.from&&form.to&&(
              <div style={{background:'rgba(56,189,248,0.08)',border:'1px solid var(--border2)',borderRadius:8,padding:'10px 14px',marginTop:8,fontSize:13,color:'var(--accent)'}}>
                <Calendar size={14} style={{display:'inline',marginRight:6}}/>Duration: <strong>{calcDays(form.from,form.to)} day(s)</strong>
              </div>
            )}
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={()=>setShowModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={submitLeave}>Submit Request</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}