import React, { useState, useEffect } from 'react';
import { Plus, Check, X, Receipt } from 'lucide-react';


const categories = ['Transport','Meals','Equipment','Training','Entertainment','Other'];
const catColors  = { Transport:'#38bdf8',Meals:'#34d399',Equipment:'#818cf8',Training:'#fb923c',Entertainment:'#f472b6',Other:'#94a3b8' };

export default function Expenses() {
  const [claims, setClaims]     = useState([]);
  const [tab, setTab]           = useState('All');
  const [showModal, setShowModal] = useState(false);
  const [form, setForm]         = useState({ empId:1, category:'Transport', amount:'', date:'', desc:'' });

  const tabs     = ['All','Pending','Approved','Rejected'];
  const filtered = tab==='All' ? claims : claims.filter(c=>c.status===tab);

  useEffect(()=>{ fetch('/api/expenses').then(r=>r.json()).then(setClaims).catch(()=>setClaims([])); },[]);
  const [employees, setEmployees] = useState([]);
  useEffect(()=>{ fetch('/api/employees').then(r=>r.json()).then(setEmployees).catch(()=>setEmployees([])); },[]);

  const approve = async id => {
    setClaims(c=>c.map(x=>x.id===id?{...x,status:'Approved'}:x));
    await fetch(`/api/expenses/${id}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status:'Approved' }) });
  };
  const reject  = async id => {
    setClaims(c=>c.map(x=>x.id===id?{...x,status:'Rejected'}:x));
    await fetch(`/api/expenses/${id}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ status:'Rejected' }) });
  };

  const submitClaim = async () => {
    if (!form.amount||!form.date||!form.desc) return;
    const body = { empId:Number(form.empId), category:form.category, amount:Number(form.amount), date:form.date, status:'Pending', desc:form.desc };
    const res = await fetch('/api/expenses', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
    const created = await res.json();
    setClaims(prev=>[...prev, created]);
    setShowModal(false);
    setForm({ empId:1, category:'Transport', amount:'', date:'', desc:'' });
  };

  const totalApproved = claims.filter(c=>c.status==='Approved').reduce((s,c)=>s+c.amount,0);
  const totalPending  = claims.filter(c=>c.status==='Pending').reduce((s,c)=>s+c.amount,0);

  return (
    <div className="page">
      <div className="page-header"><h1>Expense Claims</h1><p>Submit and manage employee expense reimbursements.</p></div>

      <div className="stat-grid">
        <div className="stat-card blue"><div className="stat-label">Total Claims</div><div className="stat-value blue">{claims.length}</div></div>
        <div className="stat-card green"><div className="stat-label">Approved Amount</div><div className="stat-value green">${totalApproved.toFixed(2)}</div></div>
        <div className="stat-card orange"><div className="stat-label">Pending Amount</div><div className="stat-value orange">${totalPending.toFixed(2)}</div></div>
        <div className="stat-card purple"><div className="stat-label">Pending Review</div><div className="stat-value purple">{claims.filter(c=>c.status==='Pending').length}</div></div>
      </div>

      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <div className="tabs">{tabs.map(t=><button key={t} className={`tab ${tab===t?'active':''}`} onClick={()=>setTab(t)}>{t}</button>)}</div>
        <button className="btn btn-primary" onClick={()=>setShowModal(true)}><Plus size={14}/> New Claim</button>
      </div>

      <div className="card" style={{padding:0,overflow:'hidden'}}>
        <div className="table-wrap">
          <table>
            <thead><tr><th>Employee</th><th>Category</th><th>Amount</th><th>Date</th><th>Description</th><th>Status</th><th>Actions</th></tr></thead>
            <tbody>
              {filtered.map(c=>(
                <tr key={c.id}>
                  <td><div className="emp-info"><div className="emp-avatar" style={{fontSize:11}}>{c.empName.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><span style={{fontSize:13,fontWeight:500}}>{c.empName}</span></div></td>
                  <td><span style={{display:'inline-flex',alignItems:'center',gap:6,fontSize:12,fontWeight:600,color:catColors[c.category]}}><span style={{width:7,height:7,borderRadius:'50%',background:catColors[c.category],display:'inline-block'}}/>{c.category}</span></td>
                  <td style={{fontFamily:'var(--font-display)',fontWeight:700}}>${c.amount.toFixed(2)}</td>
                  <td style={{color:'var(--text-2)',fontSize:13}}>{c.date}</td>
                  <td style={{color:'var(--text-2)',fontSize:12,maxWidth:180}}>{c.desc}</td>
                  <td><span className={`badge ${c.status==='Approved'?'badge-green':c.status==='Pending'?'badge-orange':'badge-red'}`}>{c.status}</span></td>
                  <td>
                    {c.status==='Pending'&&(
                      <div style={{display:'flex',gap:6}}>
                        <button className="btn btn-sm btn-outline" style={{color:'var(--accent3)',borderColor:'var(--accent3)'}} onClick={()=>approve(c.id)}><Check size={12}/></button>
                        <button className="btn btn-sm btn-danger" onClick={()=>reject(c.id)}><X size={12}/></button>
                      </div>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filtered.length===0&&<div style={{textAlign:'center',padding:40,color:'var(--text-3)'}}>No claims found.</div>}
        </div>
      </div>

      {showModal&&(
        <div className="modal-overlay" onClick={()=>setShowModal(false)}>
          <div className="modal" onClick={e=>e.stopPropagation()}>
            <div className="modal-title">New Expense Claim</div>
            <div className="modal-sub">Submit a claim for reimbursement.</div>
            <div className="form-grid">
              <div className="form-group" style={{gridColumn:'1/-1'}}><label className="form-label">Employee</label><select className="form-select" value={form.empId} onChange={e=>setForm({...form,empId:e.target.value})}>{employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></div>
              <div className="form-group"><label className="form-label">Category</label><select className="form-select" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{categories.map(c=><option key={c}>{c}</option>)}</select></div>
              <div className="form-group"><label className="form-label">Amount (SGD)</label><input className="form-input" type="number" step="0.01" placeholder="e.g. 45.60" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></div>
              <div className="form-group"><label className="form-label">Date</label><input className="form-input" type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></div>
              <div className="form-group"><label className="form-label">Description</label><input className="form-input" placeholder="Brief description…" value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})}/></div>
            </div>
            <div className="modal-actions">
              <button className="btn btn-outline" onClick={()=>setShowModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={submitClaim}><Receipt size={14}/> Submit Claim</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}