import React, { useState, useEffect } from 'react';
import { Star, TrendingUp, Users } from 'lucide-react';


export default function Performance() {
  const [reviews, setReviews] = useState([]);
  const [employees, setEmployees] = useState([]);
  useEffect(()=>{
    fetch('/api/performance').then(r=>r.json()).then(setReviews).catch(()=>setReviews([]));
    fetch('/api/employees').then(r=>r.json()).then(setEmployees).catch(()=>setEmployees([]));
  },[]);
  const avgRating = (reviews.reduce((sum, r) => sum + (r.rating||0), 0) / Math.max(1,reviews.length)).toFixed(1);
  const flagged = reviews.filter(r => r.rating < 4.2);

  return (
    <div className="page">
      <div className="page-header"><h1>Performance Analysis</h1><p>Review employee performance, ratings, and coaching priorities.</p></div>
      <div className="stat-grid" style={{ gridTemplateColumns:'repeat(4,1fr)' }}>
        <div className="stat-card blue"><div className="stat-label">Avg Rating</div><div className="stat-value blue">{avgRating}</div></div>
        <div className="stat-card green"><div className="stat-label">Reviews</div><div className="stat-value green">{reviews.length}</div></div>
        <div className="stat-card orange"><div className="stat-label">Employees</div><div className="stat-value orange">{employees.length}</div></div>
        <div className="stat-card purple"><div className="stat-label">Flagged</div><div className="stat-value purple">{flagged.length}</div></div>
      </div>

      <div className="card" style={{ padding:0, overflow:'hidden' }}>
        <div className="table-wrap">
          <table>
            <thead><tr><th>Employee</th><th>Rating</th><th>Summary</th><th>Trend</th></tr></thead>
            <tbody>
              {reviews.map(review => (
                <tr key={review.id}>
                  <td>{review.name}</td>
                  <td style={{ fontWeight:700 }}>{review.rating}</td>
                  <td>{review.review}</td>
                  <td><TrendingUp size={16} color={review.rating > 4.3 ? '#22c55e' : '#f97316'} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:18, marginTop:20 }}>
        <div className="card" style={{ padding:'20px' }}>
          <div className="card-header"><div className="card-title"><Users size={16} style={{ marginRight:8 }} />Performance Spotlight</div></div>
          <div style={{ display:'grid', gap:12, marginTop:10 }}>
            {reviews.slice(0,3).map(review => (
              <div key={review.id} style={{ padding:12, background:'var(--bg-deep)', borderRadius:10 }}>
                <div style={{ fontWeight:600 }}>{review.name}</div>
                <div style={{ fontSize:13, color:'var(--text-2)' }}>{review.review}</div>
              </div>
            ))}
          </div>
        </div>
        <div className="card" style={{ padding:'20px' }}>
          <div className="card-header"><div className="card-title"><Star size={16} style={{ marginRight:8 }} />Coaching Focus</div></div>
          <div style={{ marginTop:10, color:'var(--text-2)' }}>
            Highlight lower-rated reviews for coaching and development:
            <ul style={{ marginTop:10, paddingLeft:20, color:'var(--text-2)' }}>
              {flagged.map(review => <li key={review.id}>{review.name} — {review.rating}</li>)}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}
